/usr/bin/zsh -lc "python - <<'PY'
import json,math
from pathlib import Path
p=json.loads(Path('predictions.json').read_text())
assert set(p)=={f'fig_{i:02}.png' for i in range(1,31)}
for ss in p.values():
 for s in ss:
  assert s['name']
  for q in s['data']:assert set(q)=={'x','y'} and all(math.isfinite(v) for v in q.values())
for f in Path('.').glob('batch_*.png'):f.unlink()
Path('extract.py').unlink()
for f in Path('__pycache__').glob('extract.*.pyc'):f.unlink()
if Path('__pycache__').exists() and not list(Path('__pycache__').iterdir()):Path('__pycache__').rmdir()
print('Validated 30 figures;',sum(len(s['data']) for ss in p.values() for s in ss),'points.')
PY"

